A['admin-order-note']=el=>{if(!can('dispatch')&&App.state.role!=='admin'){toast('当前角色只能查看订单');return;}App.temp.adminOrderId=el.dataset.id;dialog('添加订单处理备注',`<form id="order-note-form" data-form="save-order-note">${textarea('处理备注 *','reason','',500,'required minlength="3"')}</form>`,`<button class="btn" type="submit" form="order-note-form">保存备注</button>`);};
