V.dispatch=()=>{const o=App.currentOrder(),selected=App.temp.dispatchWorker||'w1',list=workerData().filter(w=>w.online&&w.city===(o.city||'深圳')&&w.skills.includes(o.category));return adminPage('人工派单',`关联订单 ${e(o.id)} · 候选师傅的资格与匹配依据透明可查`,`${notice('人工指派也需满足技能、在线状态与城市范围；改派须填写原因，通知原师傅与业主。','orange')}<div class="detail-grid"><div>${panel('推荐候选师傅',`${list.length?list.map(w=>`<div class="candidate-card ${w.id===selected?'selected':''}"><label class="flex gap12"><input type="radio" name="candidate" value="${w.id}" ${w.id===selected?'checked':''} data-change="dispatch-candidate" aria-label="选择${e(w.name)}"><span style="flex:1">${avatar(w.name,'',w.color)}<span class="candidate-main"><strong>${e(w.name)} ${badge(w.title,'orange')}</strong><small>${w.rating}分 · ${w.orders}单 · ${e(w.skills.join(' / '))}</small></span></span></label><div class="candidate-meta"><div><small>顺路指数</small><strong>${w.match}%</strong></div><div><small>距离</small><strong>${w.distance}km</strong></div><div><small>响应时长</small><strong>${w.response}</strong></div><div><small>服务信用</small><strong>${w.credit}分</strong></div></div></div>`).join(''):empty('暂无符合条件的在线师傅','可联系师傅上线或与用户协商改约。','','')}`)}</div><div class="stack">${panel('待处理订单',`${orderSummary(o)}<div class="mt12">${row('当前状态',statusBadge(o))}${row('预约时间',e(o.time))}${row('服务地址',`<span style="font-size:11px">${e(o.address)}</span>`)}</div>`)}${panel('确认指派',`<form id="dispatch-form" data-form="dispatch-submit">${textarea('指派或改派理由 *','reason',App.temp.dispatchReason||'',300,'required minlength="5" data-input="dispatch-reason" placeholder="请说明人工介入的原因"')}<button type="submit" class="btn full" ${!list.length||!can('dispatch')||!['dispatching','offered','accepted','enroute'].includes(o.status)?'disabled':''}>${icon('route',16)} 确认指派并通知师傅</button></form><p class="mt12" style="font-size:10px">指派后为“待师傅确认”，只有师傅接下邀请才进入已接单。</p>`)}</div></div>`,linkBtn('返回订单','order','secondary',{id:o.id}));};
