A['dispatch-submit']=(f,fd)=>{if(!requireRight('dispatch'))return;const o=App.currentOrder(),id=App.temp.dispatchWorker||'w1',w=workerData().find(w=>w.id===id);if(!w?.online||!w.skills.includes(o.category)||w.city!==(o.city||'深圳')){toast('师傅不满足在线、技能或城市条件');return;}if(!['dispatching','offered','accepted','enroute'].includes(o.status)){toast('当前订单不可改派，请先处理异常');return;}confirmAction('确认人工派单',`将<strong>${e(o.title)}</strong>指派给${e(w.name)}。师傅确认后才会正式接单。`,()=>{const before=o.workerId||'无';App.updateOrder(o.id,{status:'offered',workerId:id,offerExpiresAt:Date.now()+App.state.config.timeout*1000,dispatchReason:fd.get('reason')},'平台指派'+w.name+'，等待师傅确认');App.log('派单','人工指派',o.id,fd.get('reason'),before,id);App.temp.dispatchReason='';App.go('order',{id:o.id});},'确认指派');};
