V.worker=()=>{const w=workerData().find(w=>w.id===App.query.get('id'))||workerData()[0],list=App.state.orders.filter(o=>o.workerId===w.id);return adminPage('师傅详情',`${e(w.name)} · 认证与服务档案`,`${panel('师傅基本资料',`<div class="flex gap12">${avatar(w.name,'lg',w.color)}<div><h2 style="font-size:21px">${e(w.name)}</h2><div class="tag-row mt8">${badge('已实名认证','green')}${badge(w.title,'orange')}${badge(w.online?'当前在线':'当前离线',w.online?'green':'gray')}</div></div></div><div class="admin-info-grid mt16">${row('手机号','138****5678')}${row('身份资料','已脱敏 · 仅授权核验')}${row('所在城市',w.city+'市 '+w.area)}${row('从业年限',w.years+'年')}${row('技能品类',w.skills.join(' / '))}${row('综合评分',w.rating+' / 5')}${row('完成订单',w.orders+'单')}${row('信用分',w.credit+'分')}</div>`)}<div class="detail-grid">${panel('关联服务订单',orderTable(list))}${panel('操作与认证',`${row('实名认证',badge('已通过','green'))}${row('技能认证',badge('已通过','green'))}${row('健康证明','按特定场景要求补充')}<div class="stack mt16">${linkBtn('信用记录与调整','credit','secondary full')}${act(w.suspended?'恢复接单':'暂停接单','worker-suspend',`data-id="${w.id}"`,'workers','btn secondary full')}</div>`)}</div>`,linkBtn('返回师傅列表','workers','secondary'));};
A['worker-suspend']=el=>{if(!requireRight('workers'))return;App.temp.targetWorker=el.dataset.id;const w=workerData().find(w=>w.id===el.dataset.id);dialog(w.suspended?'恢复师傅接单':'暂停师傅接单',`<form id="worker-suspend-form" data-form="worker-suspend-confirm">${textarea('处理理由 *','reason','',300,'required minlength="5"')}${notice('需要审计留痕，已在履约的订单应另行安排。','orange')}</form>`,`<button class="btn" type="submit" form="worker-suspend-form">确认处理</button>`);};
