V.audits=()=>{const filter=App.query.get('status')||'pending',list=App.state.applications.filter(a=>(filter==='all'||a.status===filter)&&(!App.state.adminCity||App.state.adminCity==='all'||a.city===App.state.adminCity));return adminPage('师傅入驻审核','核验身份、技能与服务区域，保证履约供给质量',`<div class="panel"><div class="tabs">${[['pending','待审核'],['supplement','待补材料'],['approved','已通过'],['rejected','已驳回'],['all','全部']].map(([s,l])=>`<a class="tab ${filter===s?'active':''}" href="#/audits?status=${s}">${l}</a>`).join('')}</div>${table(['申请编号','师傅姓名','联系电话','服务城市','擅长品类','提交时间','状态','操作'],list.map(a=>[`<span class="table-primary">${e(a.id)}</span>`,`<strong>${e(a.name)}</strong>`,e(a.phone),e(a.city),e(a.skill),e(a.date),badge({pending:'待审核',supplement:'待补件',approved:'已通过',rejected:'已驳回'}[a.status],a.status==='approved'?'green':'orange'),`<div class="table-actions"><a href="#/audit?id=${a.id}">核验资料</a></div>`]))}${pagination(list.length,1,20)}</div>`);};
V.audit=()=>{const a=App.state.applications.find(a=>a.id===App.query.get('id'))||App.state.applications[0];if(!a)return adminPage('审核详情','暂无待审核申请',empty('暂无师傅入驻申请','师傅端提交后会显示在这里。','audits','返回列表'));return adminPage('入驻审核详情',`申请编号 ${e(a.id)} · 逐项核实后决定审核结果`,`${panel('申请资料',`<div class="admin-info-grid">${row('申请姓名',e(a.name))}${row('联系电话',e(a.phone))}${row('服务城市',e(a.city))}${row('从业经验',a.years+'年')}${row('技能品类',e(a.skill))}${row('申请状态',badge({pending:'待审核',approved:'已通过',supplement:'待补件',rejected:'已驳回'}[a.status],a.status==='approved'?'green':'orange'))}</div><div class="audit-docs mt24">${[['身份证正面','front','credit'],['身份证反面','back','credit'],['技能证明','skill','file']].map(([n,k,i])=>`<div>${a.photos?.[k]?.[0]?`<img src="${a.photos[k][0]}" alt="${n}演示材料">`:`<div class="audit-doc-icon">${icon(i,38)}<p>演示材料缩略示意</p></div>`}<small>${n} · 仅授权核验</small></div>`).join('')}</div>`)}<div class="detail-grid">${panel('审核要点',`<form id="audit-form"><div class="stack"><label class="check-label"><input name="identity" type="checkbox"><span>已核实身份材料与实名认证信息一致</span></label><label class="check-label"><input name="skills" type="checkbox"><span>已核实技能证书或从业证明</span></label><label class="check-label"><input name="area" type="checkbox"><span>已确认服务区域与可接品类</span></label></div><div class="mt24">${textarea('审核意见（补件或驳回必须填写）','reason',a.reason||'',500)}</div><div class="flex gap12">${act('通过审核','audit-decision',`data-id="${a.id}" data-decision="approved"`,'workers','btn')}${act('要求补充材料','audit-decision',`data-id="${a.id}" data-decision="supplement"`,'workers','btn secondary')}${act('驳回申请','audit-decision',`data-id="${a.id}" data-decision="rejected"`,'workers','btn secondary')}</div></form>`)}${panel('处理说明',`${notice('审核结果同步到师傅端。未通过前可浏览页面，不可上线接单。')}<div class="mt16">${timeLine([[a.status==='approved'?'已审核通过':a.status==='supplement'?'已要求补充材料':'待平台核验','当前'],['师傅提交申请资料',a.date]])}</div>`)}</div>`,linkBtn('返回审核列表','audits','secondary'));};
A['audit-decision']=el=>{if(!requireRight('workers'))return;const form=document.getElementById('audit-form'),fd=new FormData(form),decision=el.dataset.decision,a=App.state.applications.find(a=>a.id===el.dataset.id);if(!a||a.status==='approved'){toast('申请已审核通过，无需重复处理');return;}if(decision==='approved'&&!['identity','skills','area'].every(k=>fd.get(k))){toast('通过前请逐项勾选身份、技能和服务区域核验');return;}if(decision!=='approved'&&String(fd.get('reason')).trim().length<5){toast('请填写至少5字的补件或驳回原因');return;}confirmAction('确认审核结果',`${e(a.name)}的入驻申请将设置为<strong>${{approved:'审核通过',supplement:'待补材料',rejected:'驳回'}[decision]}</strong>，确认提交？`,()=>{const before=a.status;a.status=decision;a.reason=String(fd.get('reason')||'资料核验通过');if(App.state.myApplication?.id===a.id){App.state.myApplication={...a};App.state.workerVerified=decision==='approved';}App.log('师傅审核',decision,a.id,a.reason,before,decision);App.save();App.render();toast('审核结果已同步师傅端');});};
